// Super Mango: each standard cursor is created once and reused; creating one on
// every call leaked a GLFW cursor per change. glfwTerminate frees them all, and
// ClosePlatform forgets them so a later window creates fresh ones.
static GLFWcursor *superMangoStandardCursors[11] = { 0 };

void SetMouseCursor(int cursor)
{
    CORE.Input.Mouse.cursor = cursor;
    if (cursor == MOUSE_CURSOR_DEFAULT) glfwSetCursor(platform.handle, NULL);
    else if ((cursor > 0) && (cursor < 11))
    {
        // NOTE: Mapping internal GLFW enum values to MouseCursor enum values
        if (superMangoStandardCursors[cursor] == NULL) superMangoStandardCursors[cursor] = glfwCreateStandardCursor(0x00036000 + cursor);
        glfwSetCursor(platform.handle, superMangoStandardCursors[cursor]);
    }
}

void ClosePlatform(void)
{
    glfwDestroyWindow(platform.handle);
    glfwTerminate();
    // Super Mango: glfwTerminate destroyed the cached standard cursors.
    for (int i = 0; i < 11; i++) superMangoStandardCursors[i] = NULL;
